    const productId=Number(special?.product_id);
    const name=String(special?.name||'').trim();
    if(!Number.isInteger(productId)||productId<=0) throw new Error('ID de producto inválido');
    if(!name) throw new Error('Nombre de producto obligatorio');
    const num=(v,fallback=0)=>{const n=Number(v);return Number.isFinite(n)?n:fallback};
    const int=(v,fallback)=>{const n=Number(v);return Number.isInteger(n)?n:fallback};
    const bool=(v,fallback)=>typeof v==='boolean'?v:fallback;
    const categoryId=int(special?.category_id,null),uomId=int(special?.uom_id,null);
    if(!categoryId||!uomId) throw new Error('Categoría y unidad son obligatorias');
    const q=`CALL public.sp_ruben_actualizar_producto(
