      ${uomId},
      '${esc(special?.write_uid||'Ruben')}',
      false
    )`;
    return [{json:{action,mode,product_id:productId,query:q}}];
  }
  const rawItems=Array.isArray(body.items)
    ? body.items
    : (Array.isArray(body.names)?body.names.map(name=>({descripcion:name,codigo:''})):[]);
  const items=rawItems.slice(0,100).map((item,index)=>({
    item_index:index,
    descripcion:String(item?.descripcion||'').trim(),
    codigo:String(item?.codigo||'').trim()
  })).filter(item=>item.descripcion||item.codigo);
  if(!items.length) return [{json:{action,query:`SELECT 'product_lookup'::text AS action, NULL::int AS item_index, NULL::text AS requested_name, NULL::text AS requested_code, NULL::int AS product_id, NULL::text AS product_name, NULL::text AS match_method, 0::int AS match_count WHERE false`}}];

  const itemsJson=JSON.stringify(items).replace(/'/g,"''");
  const query=`
WITH requested AS (
  SELECT
    (x->>'item_index')::int AS item_index,
    btrim(COALESCE(x->>'descripcion','')) AS requested_name,
    btrim(COALESCE(x->>'codigo','')) AS requested_code
  FROM jsonb_array_elements('${itemsJson}'::jsonb) AS x
),
matches AS (
  SELECT
    r.item_index,
    r.requested_name,
    r.requested_code,
    COUNT(p."ID") FILTER (
      WHERE r.requested_name<>'' AND btrim(p."Name")=r.requested_name
    )::int AS exact_count,
    MIN(p."ID") FILTER (
      WHERE r.requested_name<>'' AND btrim(p."Name")=r.requested_name
    )::int AS exact_id,
    MIN(p."Name") FILTER (
      WHERE r.requested_name<>'' AND btrim(p."Name")=r.requested_name
    )::text AS exact_name,
    COUNT(p."ID") FILTER (
      WHERE r.requested_code<>'' AND strpos(lower(p."Name"),lower(r.requested_code))>0
    )::int AS code_count,
    MIN(p."ID") FILTER (
      WHERE r.requested_code<>'' AND strpos(lower(p."Name"),lower(r.requested_code))>0
    )::int AS code_id,
    MIN(p."Name") FILTER (
      WHERE r.requested_code<>'' AND strpos(lower(p."Name"),lower(r.requested_code))>0
    )::text AS code_name
  FROM requested r
  LEFT JOIN public."Products" p
    ON (r.requested_name<>'' AND btrim(p."Name")=r.requested_name)
    OR (r.requested_code<>'' AND strpos(lower(p."Name"),lower(r.requested_code))>0)
  GROUP BY r.item_index,r.requested_name,r.requested_code
)
SELECT
  'product_lookup'::text AS action,
  item_index,
  requested_name,
  requested_code,
  CASE
    WHEN exact_count=1 THEN exact_id
    WHEN exact_count=0 AND code_count=1 THEN code_id
    ELSE NULL
  END::int AS product_id,
  CASE
    WHEN exact_count=1 THEN exact_name
    WHEN exact_count=0 AND code_count=1 THEN code_name
    ELSE NULL
  END::text AS product_name,
  CASE
    WHEN exact_count=1 THEN 'exact_name'
    WHEN exact_count=0 AND code_count=1 THEN 'code_in_name'
    WHEN exact_count>1 THEN 'duplicate_name'
    WHEN exact_count=0 AND code_count>1 THEN 'duplicate_code'
    ELSE 'not_found'
  END::text AS match_method,
  CASE
    WHEN exact_count>0 THEN exact_count
    ELSE code_count
  END::int AS match_count
FROM matches
ORDER BY item_index`;
  return [{json:{action,items,query}}];
}

const company=String(body.company||'').trim();
const date=String(body.date||'').trim();
if(!company||company.length>160) throw new Error('Compañía inválida');
if(!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Fecha inválida');
const esc=s=>s.replace(/'/g,"''");
const c=esc(company), d=esc(date);
const query=`
WITH movimientos AS (
  SELECT
    (fecha AT TIME ZONE 'America/Argentina/Buenos_Aires')::date AS d,
    estado,
    COALESCE(total,0)::numeric AS total
  FROM public.iva_pedidos
  WHERE compania='${c}'
    AND estado IN ('Presupuesto','Pedido','Terminado')

  UNION ALL

  SELECT
    (fecha AT TIME ZONE 'America/Argentina/Buenos_Aires')::date AS d,
    'Facturado'::text AS estado,
    COALESCE(total_venta,0)::numeric AS total
  FROM public.iva_ventas
  WHERE compania='${c}'
)
SELECT 'dashboard' AS action,'day' AS period,estado,
       COUNT(*)::int AS cantidad,
       ROUND(COALESCE(SUM(total),0)::numeric,2) AS total
FROM movimientos
WHERE d=DATE '${d}'
GROUP BY estado
UNION ALL
SELECT 'dashboard','month',estado,
       COUNT(*)::int AS cantidad,
       ROUND(COALESCE(SUM(total),0)::numeric,2) AS total
FROM movimientos
WHERE date_trunc('month',d)=date_trunc('month',DATE '${d}')
GROUP BY estado
ORDER BY period,estado`;
return [{json:{action,company,date,query}}];

